// A DOM element
let userButton = { id: "login-btn" }; // Pretend this is a real DOM node

// 1. Using a regular Map
const regularMap = new Map();
regularMap.set(userButton, { clicks: 5 });

userButton = null; // We "remove" the button from the page

// MEMORY LEAK! The button object still exists inside regularMap.
console.log(regularMap.size); // 1


// 2. Using a WeakMap
let anotherButton = { id: "logout-btn" };
const weakMap = new WeakMap();
weakMap.set(anotherButton, { clicks: 2 });

anotherButton = null; // We remove the button

// No memory leak! The WeakMap doesn't prevent garbage collection.
// We can't check weakMap.size, but behind the scenes, 
// the {id: "logout-btn"} object will be wiped from memory.
